@php
$ganttTasks=$board->columns->flatMap(fn($column)=>$column->cards)->map(fn($task)=>['id'=>$task->id,'title'=>$task->title,'column'=>$task->column->name,'progress'=>(int)$task->progress,'minutes'=>(int)($task->tracked_minutes??0),'start'=>$task->start_date?->toDateString(),'due'=>$task->due_date?->toDateString(),'done'=>(bool)$task->completed_at,'assignees'=>$task->assignees->pluck('id')->map(fn($id)=>(string)$id)->all(),'labels'=>$task->labels->pluck('id')->map(fn($id)=>(string)$id)->all(),'search'=>mb_strtolower($task->title.' '.$task->description.' '.collect($task->related_items??[])->pluck('title')->implode(' '))])->values()->all();
@endphp
<section x-show="boardView==='gantt'" x-cloak class="notes-card mb-4" x-data="taskGantt(@js($ganttTasks))" @task-progress-update.window="const task=tasks.find(t=>t.id===$event.detail.id);if(task){task.progress=$event.detail.progress;task.done=$event.detail.done}">
<div class="folder-panel-head"><div><h2>Project timeline</h2><p class="notes-hint">Scheduled dates, task progress and tracked time. Click a row to edit its schedule.</p></div><div class="notes-actions"><button type="button" class="form-chip" @click="shift(-Math.floor(count/2))">←</button><button type="button" class="form-chip" @click="anchor=taskToday()">Today</button><input type="date" class="theme-input" x-model="anchor" aria-label="Gantt start date"><select class="theme-input" x-model.number="count" aria-label="Timeline zoom"><option value="14">2 weeks</option><option value="35">5 weeks</option><option value="90">3 months</option></select><button type="button" class="form-chip" @click="shift(Math.floor(count/2))">→</button></div></div>
<div class="task-gantt-scroll"><div :style="'min-width:'+(260+count*cell)+'px'">
<div class="task-gantt-row" :style="grid"><strong class="task-gantt-name">Task / progress</strong><div><div class="task-gantt-months"><template x-for="month in months" :key="month.key"><span :style="'width:'+month.width+'px'" x-text="month.label"></span></template></div><div class="task-gantt-days"><template x-for="(day,i) in days" :key="day"><span :class="day===taskToday()?'is-today':(isWeekend(day)?'is-weekend':'')" :style="'width:'+cell+'px'" :title="day" x-text="day.slice(8)"></span></template></div></div></div>
<template x-for="task in scheduled" :key="task.id"><div class="task-gantt-row" :style="grid"><button class="task-gantt-name text-left" type="button" @click="openCard(task.id)"><strong x-text="task.title"></strong><small x-text="task.column+' · '+task.progress+'% · '+Math.round(task.minutes/6)/10+'h tracked'"></small><small x-text="(task.start||task.due)+' → '+(task.due||task.start)"></small></button><div class="task-gantt-track" :style="'background-size:'+cell+'px 100%'">
<div class="task-gantt-today" x-show="todayOffset>=0&&todayOffset<count" :style="'left:'+todayOffset*cell+'px'"></div>
<button type="button" class="task-gantt-bar" x-show="bar(task)" :style="bar(task)" @click="openCard(task.id)" :title="task.title+' · '+task.progress+'%'" :class="task.done?'is-complete':''"><span class="task-gantt-fill" :style="'width:'+task.progress+'%'"></span><span class="task-gantt-caption" x-text="task.progress+'%'"></span></button>
<span class="notes-hint pl-3" x-show="!bar(task)">Outside this date range</span></div></div></template>
</div></div>
<details class="mt-4" x-show="unscheduled.length"><summary class="text-sm font-semibold" x-text="unscheduled.length+' tasks need dates'"></summary><p class="notes-hint my-2">Set dates to place these tasks on the timeline.</p><template x-for="task in unscheduled" :key="task.id"><button type="button" class="form-chip mr-2 mb-2" @click="openCard(task.id)" x-text="task.title+' · set dates'"></button></template></details>
<p class="notes-hint mt-3" x-show="!visibleTasks.length">No matching tasks. Clear the filters or add a task.</p></section>
<style>
.task-workspace-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:20px}.task-gantt-scroll{overflow:auto;max-height:65vh;border:1px solid var(--border-soft);border-radius:12px}.task-gantt-row{display:grid;align-items:center;border-bottom:1px solid var(--border-soft);min-height:74px}.task-gantt-name{padding:12px;position:sticky;left:0;background:var(--bg-card);z-index:2;border-right:1px solid var(--border-soft);overflow:hidden;text-overflow:ellipsis}.task-gantt-name strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-gantt-name small{display:block;font-size:10px;color:var(--text-muted);margin-top:4px}.task-gantt-days,.task-gantt-months{display:flex}.task-gantt-months span{font-size:11px;font-weight:600;padding:6px 8px;background:var(--bg-glass-input);border-right:1px solid var(--border-soft);white-space:nowrap;overflow:hidden}.task-gantt-days span{flex-shrink:0;text-align:center;font-size:10px;padding:8px 0;border-right:1px solid var(--border-soft)}.task-gantt-days .is-weekend{background:var(--bg-glass-input)}.task-gantt-days .is-today{background:var(--c-primary-soft);color:var(--c-primary);font-weight:700}.task-gantt-track{height:74px;position:relative;background-image:linear-gradient(to right,transparent calc(100% - 1px),var(--border-soft) 1px)}.task-gantt-bar{position:absolute;top:22px;height:30px;border:1px solid var(--c-primary,#536dfe);border-radius:7px;background:var(--c-primary-soft,#e1e8ff);min-width:12px;overflow:hidden}.task-gantt-fill{position:absolute;inset:0 auto 0 0;background:var(--c-primary,#536dfe);opacity:.4}.task-gantt-caption{position:relative;z-index:1;font-size:10px;font-weight:600;color:var(--text-primary)}.task-gantt-today{position:absolute;top:0;bottom:0;border-left:2px solid var(--c-primary);opacity:.4}.task-gantt-bar.is-complete{border-color:#15947c;background:#dcf6ef}.task-gantt-bar.is-complete .task-gantt-fill{background:#15947c}
</style>
<script>
function taskToday(offset=0){const now=new Date();return new Date(Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()+offset)).toISOString().slice(0,10);}
function taskGantt(tasks){return{tasks,count:35,anchor:tasks.map(t=>t.start||t.due).filter(Boolean).sort()[0]||taskToday(),init(){this.$watch('anchor',()=>this.notify());this.$watch('count',()=>this.notify());this.notify();},notify(){this.$dispatch('gantt-window',{from:this.anchor,days:this.count});},get cell(){return this.count>35?18:32},get grid(){return 'grid-template-columns:260px '+(this.count*this.cell)+'px'},get days(){return Array.from({length:this.count},(_,i)=>this.dateAt(i));},get months(){const result=[];this.days.forEach(day=>{const key=day.slice(0,7);if(result.at(-1)?.key===key)result.at(-1).width+=this.cell;else result.push({key,width:this.cell,label:new Date(day+'T12:00:00Z').toLocaleDateString(undefined,{month:'long',year:'numeric',timeZone:'UTC'})});});return result;},get todayOffset(){return (new Date(taskToday()+'T00:00:00Z')-new Date(this.anchor+'T00:00:00Z'))/86400000},isWeekend(day){return [0,6].includes(new Date(day+'T00:00:00Z').getUTCDay())},dateAt(i){const date=new Date(this.anchor+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+i);return date.toISOString().slice(0,10);},shift(n){this.anchor=this.dateAt(n)},get visibleTasks(){const f=this.filters;return this.tasks.filter(t=>(!f.search||t.search.includes(f.search.toLowerCase()))&&(!f.assignees.length||f.assignees.some(id=>t.assignees.includes(String(id))))&&(!f.labels.length||f.labels.some(id=>t.labels.includes(String(id))))&&(!f.due||(f.due==='none'&&!t.due)||(f.due==='overdue'&&t.due&&t.due<taskToday()&&!t.done)||(f.due==='today'&&t.due===taskToday())||(f.due==='week'&&t.due&&t.due>=taskToday()&&t.due<=taskToday(7))));},get scheduled(){return this.visibleTasks.filter(t=>t.start||t.due)},get unscheduled(){return this.visibleTasks.filter(t=>!t.start&&!t.due)},bar(t){const a=new Date((t.start||t.due)+'T00:00:00Z'),b=new Date((t.due||t.start)+'T00:00:00Z'),anchor=new Date(this.anchor+'T00:00:00Z');const left=(a-anchor)/86400000,right=(b-anchor)/86400000;if(!Number.isFinite(left)||right<0||left>=this.count)return null;return 'left:'+Math.max(0,left)*this.cell+'px;width:'+Math.max(12,(Math.min(this.count-1,right)-Math.max(0,left)+1)*this.cell-4)+'px';}};}
</script>
